mapper.select:

where e.del_flag = '0'

    and e.enterprise_name like concat('%', #{enterpriseName}, '%')


    and e.region_id = #{regionId}


    and e.contact like concat('%', #{contact}, '%')


    and e.status = #{status}

order by e.enterprise_id desc

mapper.insert:
insert into trace_enterprise (
    region_id, enterprise_name, license_no, contact, phone, address, status, remark, create_by, create_time
) values (
    #{regionId}, #{enterpriseName}, #{licenseNo}, #{contact}, #{phone}, #{address}, #{status}, #{remark}, #{createBy}, sysdate()
)

mapper.update:
update trace_enterprise
region_id = #{regionId}, enterprise_name = #{enterpriseName}, license_no = #{licenseNo}, contact = #{contact}, phone = #{phone}, address = #{address}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where enterprise_id = #{enterpriseId}
